import hashlib

def hash_password(password):
    return hashlib.sha256(password.encode()).hexdigest()

def verify_password(password, hashed):
    return hashlib.sha256(password.encode()).hexdigest() == hashed

h = hash_password("secret123")
print(h)
print(verify_password("secret123", h))
print(verify_password("wrong", h))

import json
import base64

def make_jwt(user_id, username):
    header = {"alg": "HS256", "typ": "JWT"}
    payload = {"sub": username, "user_id": user_id, "exp": 9999999999}

    header_b64 = base64.urlsafe_b64encode(json.dumps(header).encode()).decode()
    payload_b64 = base64.urlsafe_b64encode(json.dumps(payload).encode()).decode()
    sig = "fake_signature"

    return f"{header_b64}.{payload_b64}.{sig}"

print(make_jwt(1, "alice"))

from fastapi import FastAPI, Depends

app = FastAPI()

def get_current_user(token: str):
    return token

@app.get("/me")
async def read_users_me(current_user: str = Depends(get_current_user)):
    return {"user": current_user}

from fastapi import HTTPException

def handle_task_not_found(task_id):
    print(f"Searching for task {task_id}...")
    raise HTTPException(status_code=404, detail=f"Task {task_id} not found")

def handle_unauthorized():
    raise HTTPException(status_code=401, detail="Invalid or expired token")

try:
